INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 3001, -416.5, 100, "ヤマト", 130011, 3001100, "2024/10/31 12:00:00", 2, 1, 2.1, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 3001, -416.5, 101, "ヤマト", 130011, 3001101, "2024/10/31 12:00:00", 2, 4, 5.68, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 3001, -416.5, 102, "ヤマト", 130011, 3001102, "2024/10/31 12:00:00", 1, 1, 0, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 3002, -416.5, 100, "フブキ", 130211, 3002100, "2024/10/31 12:00:00", 1, 1, 0, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 3002, -416.5, 101, "フブキ", 130211, 3002101, "2024/10/31 12:00:00", 1, 1, 0, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 3002, -416.5, 102, "フブキ", 130211, 3002102, "2024/10/31 12:00:00", 2, 5, 8.53, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 3002, -416.5, 103, "フブキ", 130211, 3002103, "2024/10/31 12:00:00", 1, 7, 5.67, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 3002, -416.5, 104, "フブキ", 130211, 3002104, "2024/10/31 12:00:00", 1, 1, 0, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 3004, -416.5, 300, "フブキ", 130211, 3002300, "2024/10/31 12:00:00", 3, 3, 0, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 3005, -416.5, 301, "フブキ", 130211, 3002400, "2024/10/31 12:00:00", 7, 7, 0, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 3003, -416.5, 200, "フブキ", 130211, 3003200, "2024/10/31 12:00:00", 1, 2, 4.4, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 3003, -416.5, 201, "フブキ", 130211, 3003201, "2024/10/31 12:00:00", 7, 7, 0, 0);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 3003, -416.5, 202, "フブキ", 130211, 3003202, "2024/10/31 12:00:00", 2, 1, 5.6, 0);
